    private class Strings(@param:StringRes val label: Int?, @param:StringRes val description: Int?)

    private val STRINGS: Map<String, Strings> = mapOf(
        "-ば" to Strings(null, R.string.inflection_ja_ba),
        "-ゃ" to Strings(null, R.string.inflection_ja_ya),
        "-ちゃ" to Strings(null, R.string.inflection_ja_cha),
        "-ちゃう" to Strings(null, R.string.inflection_ja_chau),
        "-ちまう" to Strings(null, R.string.inflection_ja_chimau),
        "-しまう" to Strings(null, R.string.inflection_ja_shimau),
        "-なさい" to Strings(null, R.string.inflection_ja_nasai),
        "-そう" to Strings(null, R.string.inflection_ja_sou),
        "-すぎる" to Strings(null, R.string.inflection_ja_sugiru),
        "-過ぎる" to Strings(null, R.string.inflection_ja_sugigiru_kanji),
        "-たい" to Strings(null, R.string.inflection_ja_tai),
        "-たら" to Strings(null, R.string.inflection_ja_tara),
        "-たり" to Strings(null, R.string.inflection_ja_tari),
        "-て" to Strings(null, R.string.inflection_ja_te),
        "-ず" to Strings(null, R.string.inflection_ja_zu),
        "-ぬ" to Strings(null, R.string.inflection_ja_nu),
        "-ん" to Strings(null, R.string.inflection_ja_n),
        "-んばかり" to Strings(null, R.string.inflection_ja_nbakari),
        "-んとする" to Strings(null, R.string.inflection_ja_ntosuru),
        "-む" to Strings(null, R.string.inflection_ja_mu),
        "-ざる" to Strings(null, R.string.inflection_ja_zaru),
        "-ねば" to Strings(null, R.string.inflection_ja_neba),
        "-く" to Strings(null, R.string.inflection_ja_ku),
        "causative" to Strings(R.string.inflection_ja_causative_label, R.string.inflection_ja_causative),
        "short causative" to Strings(R.string.inflection_ja_short_causative_label, R.string.inflection_ja_short_causative),
        "imperative" to Strings(R.string.inflection_ja_imperative_label, R.string.inflection_ja_imperative),
