        "-さ" to Strings(null, R.string.inflection_ja_sa),
        "passive" to Strings(R.string.inflection_ja_passive_label, R.string.inflection_ja_passive),
        "-た" to Strings(null, R.string.inflection_ja_ta),
        "-ます" to Strings(null, R.string.inflection_ja_masu),
        "potential" to Strings(R.string.inflection_ja_potential_label, R.string.inflection_ja_potential),
        "potential or passive" to Strings(R.string.inflection_ja_potential_or_passive_label, R.string.inflection_ja_potential_or_passive),
        "volitional" to Strings(R.string.inflection_ja_volitional_label, R.string.inflection_ja_volitional),
        "volitional slang" to Strings(R.string.inflection_ja_volitional_slang_label, R.string.inflection_ja_volitional_slang),
        "-まい" to Strings(null, R.string.inflection_ja_mai),
        "-おく" to Strings(null, R.string.inflection_ja_oku),
        "-いる" to Strings(null, R.string.inflection_ja_iru),
        "-き" to Strings(null, R.string.inflection_ja_ki),
        "-げ" to Strings(null, R.string.inflection_ja_ge),
        "-がる" to Strings(null, R.string.inflection_ja_garu),
        "-え" to Strings(null, R.string.inflection_ja_e),
        "n-slang" to Strings(R.string.inflection_ja_n_slang_label, null),
        "imperative negative slang" to Strings(R.string.inflection_ja_imperative_negative_slang_label, null),
        "kansai-ben negative" to Strings(R.string.inflection_ja_kansai_ben_negative_label, R.string.inflection_ja_kansai_ben_negative),
        "kansai-ben -て" to Strings(R.string.inflection_ja_kansai_ben_te_label, R.string.inflection_ja_kansai_ben_te),
        "kansai-ben -た" to Strings(R.string.inflection_ja_kansai_ben_ta_label, R.string.inflection_ja_kansai_ben_ta),
        "kansai-ben -たら" to Strings(R.string.inflection_ja_kansai_ben_tara_label, R.string.inflection_ja_kansai_ben_tara),
