        "kansai-ben adjective -て" to Strings(R.string.inflection_ja_kansai_ben_adjective_te_label, R.string.inflection_ja_kansai_ben_adjective_te),
        "kansai-ben adjective negative" to Strings(R.string.inflection_ja_kansai_ben_adjective_negative_label, R.string.inflection_ja_kansai_ben_adjective_negative),
        "-ましゅ" to Strings(null, R.string.inflection_ja_mashu),
        "-ください" to Strings(null, R.string.inflection_ja_kudasai),
        "-くださる" to Strings(null, R.string.inflection_ja_kudasaru),
        "-ごらん" to Strings(null, R.string.inflection_ja_goran),
        "-ごらんなさい" to Strings(null, R.string.inflection_ja_gorannasai),
        "-いただく" to Strings(null, R.string.inflection_ja_itadaku),
        "-あげる" to Strings(null, R.string.inflection_ja_ageru),
        "-くれる" to Strings(null, R.string.inflection_ja_kureru),
        "-もらう" to Strings(null, R.string.inflection_ja_morau),
        "-やる" to Strings(null, R.string.inflection_ja_yaru),
        "-さしあげる" to Strings(null, R.string.inflection_ja_sashiageru),
        "-みる" to Strings(null, R.string.inflection_ja_miru),
        "-みせる" to Strings(null, R.string.inflection_ja_miseru),
        "-ある" to Strings(null, R.string.inflection_ja_aru),
        "-いく" to Strings(null, R.string.inflection_ja_iku),
        "-くる" to Strings(null, R.string.inflection_ja_kuru),
        "-なさそう" to Strings(null, R.string.inflection_ja_nasasou),
        "-ながら" to Strings(null, R.string.inflection_ja_nagara),
        "-やがる" to Strings(null, R.string.inflection_ja_yagaru),
    )

    /** Every rule name the map knows, for checking it against the engine source. */
    val names: Set<String> get() = STRINGS.keys

    /** [transform] with the label and description in the resources' language; unknown rules keep the engine's text. */
    fun localize(resources: Resources, transform: Transform): Transform {
        val strings = STRINGS[transform.name] ?: return transform
        return transform.copy(
            label = strings.label?.let(resources::getString) ?: transform.label,
            description = strings.description?.let(resources::getString) ?: transform.description,
        )
    }
}
